// 1. Read or initialize the persistent counter in global static data
const staticData = $getWorkflowStaticData('global');
if (staticData.counter === undefined) {
  staticData.counter = 0;
}

// 2. Read all incoming items
const items = $input.all();

// 3. Iterate over each item, bump counter, wrap 1–4, and compute scheduledTime
const results = items.map(item => {
  // Increment and wrap back to 1 after 4
  staticData.counter += 1;
  if (staticData.counter > 4) {
    staticData.counter = 1;
  }

  // Parse finished_at or use current date
  const raw = item.json.finished_at;
  const baseDate = raw ? new Date(raw) : new Date();
  if (isNaN(baseDate.getTime())) {
    throw new Error(`Invalid date "${raw}" on item`);
  }

  // Add days based on the counter (1–4)
  baseDate.setDate(baseDate.getDate() + staticData.counter);

  return {
    json: {
      scheduledTime: baseDate.toISOString(),
      counter: staticData.counter,
    },
  };
});

// 4. Return array of { json: { … } } items
return results;
